214	                {activeSource === "monthly" && "Top-up & bonus credits never expire."}
215	              </p>
216	            )}
217	          </div>
218	        </TooltipProvider>
219	
220	        {isLow && total > 0 && (
221	          <div className="rounded-md bg-destructive/10 px-3 py-2 text-xs font-medium text-destructive flex items-center gap-1.5">
222	            <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
223	            Low credits — top up to keep ranking resumes.
224	          </div>
225	        )}
226	        {total === 0 && (
227	          <div className="rounded-md bg-destructive/10 px-3 py-2 text-xs font-medium text-destructive flex items-center gap-1.5">
228	            <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
229	            No credits left — buy a pack or upgrade to continue ranking.
230	          </div>
231	        )}
232	        </>
233	        )}
234	      </CardContent>
235	    </Card>
236	  );
237	};
238	
239	export default AccountInfoCard;
