30	    queryKey: ["platform_config"],
31	    queryFn: async (): Promise<PlatformConfig> => {
32	      const { data, error } = await supabase.rpc("get_public_platform_config");
33	      if (error || !data) return DEFAULTS;
34	      // RPC RETURNS TABLE gives an array; pick first row
35	      const row = Array.isArray(data) ? data[0] : data;
36	      if (!row) return DEFAULTS;
37	      return { ...DEFAULTS, ...row };
